# Generated by build.py from recipe.yml for recipe xmpp-require-tls-before-login. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'open.xml'), "<?xml version='1.0'?><stream:stream to='127.0.0.1' xmlns='jabber:client' xmlns:stream='http://etherx.jabber.org/streams' version='1.0'>")
[IO.File]::WriteAllText((Join-Path $PWD 'login.xml'), "<?xml version='1.0'?><stream:stream to='127.0.0.1' xmlns='jabber:client' xmlns:stream='http://etherx.jabber.org/streams' version='1.0'><auth xmlns='urn:ietf:params:xml:ns:xmpp-sasl' mechanism='PLAIN'>AGFsaWNlAHMzY3JldA==</auth>")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--cert', 'server.pem', '--key', 'server.key', '--user', 'alice:s3cret', 'xmpp://127.0.0.1:8080/', 'xmpps://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --cacert server.pem -u alice:s3cret xmpp://127.0.0.1:8080/127.0.0.1 } finally { Stop-Process $server0 }
